            new() { Id = 11, Code = "PHYS 101", Title = "General Physics I", Description = "Classical mechanics including kinematics, Newton's laws, work and energy, momentum, rotational motion, and gravitation. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", DepartmentId = "phys", Instructor = new() { Name = "Dr. Thomas Grant", Bio = "Dr. Grant is an experimental physicist specializing in condensed matter. He received his Ph.D. from Caltech.", Email = "tgrant@university.edu", PhotoUrl = "" } },
            new() { Id = 12, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, Gauss's law, electric potential, capacitance, current, magnetic fields, Faraday's law, and Maxwell's equations.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Fri Lab 1:00–3:50 PM", DepartmentId = "phys", Instructor = new() { Name = "Dr. Maria Santos", Bio = "Dr. Santos is a theoretical physicist with expertise in electromagnetic theory. She holds a Ph.D. from ETH Zurich.", Email = "msantos@university.edu", PhotoUrl = "" } },
            new() { Id = 13, Code = "PHYS 320", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, hydrogen atom, angular momentum, spin, and multi-particle systems.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentId = "phys", IsFeatured = false, Instructor = new() { Name = "Dr. Thomas Grant", Bio = "Dr. Grant is an experimental physicist specializing in condensed matter. He received his Ph.D. from Caltech.", Email = "tgrant@university.edu", PhotoUrl = "" } }
