namespace CourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Slug { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Instructor
{
    public string Name { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string PhotoUrl { get; set; } = string.Empty;
}

namespace CourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public Instructor Instructor { get; set; } = new();
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace CourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Student name is required.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

namespace CourseCatalog.Services;

using CourseCatalog.Models;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = "cs", Name = "Computer Science", Slug = "computer-science", Description = "Explore the theory and practice of computing, from algorithms and data structures to artificial intelligence and software engineering." },
            new() { Id = "math", Name = "Mathematics", Slug = "mathematics", Description = "Study the foundations of mathematics including calculus, linear algebra, statistics, and abstract reasoning." },
            new() { Id = "eng", Name = "English", Slug = "english", Description = "Develop critical reading, analytical writing, and literary interpretation skills across genres and historical periods." },
            new() { Id = "phys", Name = "Physics", Slug = "physics", Description = "Investigate the fundamental laws of nature from classical mechanics to quantum physics and thermodynamics." }
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, data structures, and basic object-oriented programming.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = "cs", IsFeatured = true, Instructor = new() { Name = "Dr. Sarah Chen", Bio = "Dr. Chen has over 15 years of experience teaching introductory programming. She holds a Ph.D. in Computer Science from MIT and has published extensively on CS education.", Email = "schen@university.edu", PhotoUrl = "" } },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "A comprehensive study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming, greedy algorithms).", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentId = "cs", IsFeatured = false, Instructor = new() { Name = "Dr. James Rodriguez", Bio = "Dr. Rodriguez specializes in algorithm optimization and competitive programming. He earned his Ph.D. from Stanford and previously worked at Google Research.", Email = "jrodriguez@university.edu", PhotoUrl = "" } },
            new() { Id = 3, Code = "CS 310", Title = "Artificial Intelligence", Description = "Introduction to the core concepts of AI including search algorithms, knowledge representation, machine learning fundamentals, natural language processing, and neural networks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentId = "cs", IsFeatured = true, Instructor = new() { Name = "Dr. Aisha Patel", Bio = "Dr. Patel is an AI researcher with a focus on natural language processing. She completed her Ph.D. at Carnegie Mellon and has worked at DeepMind.", Email = "apatel@university.edu", PhotoUrl = "" } },
            new() { Id = 4, Code = "CS 350", Title = "Software Engineering", Description = "Principles and practices of software development including agile methodologies, version control, testing, CI/CD pipelines, and collaborative development in team environments.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentId = "cs", Instructor = new() { Name = "Dr. Sarah Chen", Bio = "Dr. Chen has over 15 years of experience teaching introductory programming. She holds a Ph.D. in Computer Science from MIT and has published extensively on CS education.", Email = "schen@university.edu", PhotoUrl = "" } },

            // Mathematics
            new() { Id = 5, Code = "MATH 151", Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to rates of change, optimization, and area computation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentId = "math", IsFeatured = true, Instructor = new() { Name = "Dr. Michael Okafor", Bio = "Dr. Okafor is an award-winning mathematics educator with a passion for making calculus accessible. He received his Ph.D. from Princeton.", Email = "mokafor@university.edu", PhotoUrl = "" } },
            new() { Id = 6, Code = "MATH 220", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors, with applications to systems of equations and geometry.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentId = "math", Instructor = new() { Name = "Dr. Lisa Wang", Bio = "Dr. Wang specializes in applied mathematics and numerical methods. She holds a Ph.D. from UC Berkeley.", Email = "lwang@university.edu", PhotoUrl = "" } },
            new() { Id = 7, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, regression analysis, and Bayesian inference with real-world applications.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:20 PM", DepartmentId = "math", Instructor = new() { Name = "Dr. Michael Okafor", Bio = "Dr. Okafor is an award-winning mathematics educator with a passion for making calculus accessible. He received his Ph.D. from Princeton.", Email = "mokafor@university.edu", PhotoUrl = "" } },

            // English
            new() { Id = 8, Code = "ENG 101", Title = "College Composition", Description = "Develop essential academic writing skills including argumentation, research methods, source evaluation, and rhetorical analysis across multiple genres.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = "eng", Instructor = new() { Name = "Prof. Emily Foster", Bio = "Prof. Foster is a published author and rhetoric specialist. She holds an MFA from the Iowa Writers' Workshop.", Email = "efoster@university.edu", PhotoUrl = "" } },
            new() { Id = 9, Code = "ENG 215", Title = "American Literature", Description = "Survey of major American literary works from the colonial period to the present, examining themes of identity, democracy, and cultural change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", DepartmentId = "eng", IsFeatured = false, Instructor = new() { Name = "Dr. Robert Kim", Bio = "Dr. Kim is a scholar of 20th-century American fiction. He earned his Ph.D. from Yale and has published three books on American literary movements.", Email = "rkim@university.edu", PhotoUrl = "" } },
            new() { Id = 10, Code = "ENG 310", Title = "Creative Writing Workshop", Description = "An intensive workshop-style course in fiction and poetry writing. Students produce original work, participate in peer review, and study craft techniques.", Credits = 3, Schedule = "Wed 3:00–5:50 PM", DepartmentId = "eng", IsFeatured = true, Instructor = new() { Name = "Prof. Emily Foster", Bio = "Prof. Foster is a published author and rhetoric specialist. She holds an MFA from the Iowa Writers' Workshop.", Email = "efoster@university.edu", PhotoUrl = "" } },

            // Physics
            new() { Id = 11, Code = "PHYS 101", Title = "General Physics I", Description = "Classical mechanics including kinematics, Newton's laws, work and energy, momentum, rotational motion, and gravitation. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", DepartmentId = "phys", Instructor = new() { Name = "Dr. Thomas Grant", Bio = "Dr. Grant is an experimental physicist specializing in condensed matter. He received his Ph.D. from Caltech.", Email = "tgrant@university.edu", PhotoUrl = "" } },
            new() { Id = 12, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric fields, Gauss's law, electric potential, capacitance, current, magnetic fields, Faraday's law, and Maxwell's equations.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:20 PM + Fri Lab 1:00–3:50 PM", DepartmentId = "phys", Instructor = new() { Name = "Dr. Maria Santos", Bio = "Dr. Santos is a theoretical physicist with expertise in electromagnetic theory. She holds a Ph.D. from ETH Zurich.", Email = "msantos@university.edu", PhotoUrl = "" } },
            new() { Id = 13, Code = "PHYS 320", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave-particle duality, Schrödinger equation, hydrogen atom, angular momentum, spin, and multi-particle systems.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", DepartmentId = "phys", IsFeatured = false, Instructor = new() { Name = "Dr. Thomas Grant", Bio = "Dr. Grant is an experimental physicist specializing in condensed matter. He received his Ph.D. from Caltech.", Email = "tgrant@university.edu", PhotoUrl = "" } }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartmentBySlug(string slug) =>
        _departments.FirstOrDefault(d => d.Slug.Equals(slug, StringComparison.OrdinalIgnoreCase));

    public Department? GetDepartmentById(string id) =>
        _departments.FirstOrDefault(d => d.Id.Equals(id, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetAllCourses() => _courses;

    public List<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourseById(int id) =>
        _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(string departmentId) =>
        _courses.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase)).ToList();

    public List<Course> SearchCourses(string? searchTerm, string? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }
}

