@page "/courses"
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Course Catalog - Crestwood University</PageTitle>

<div class="container my-5">
    <h1 class="mb-4">Course Catalog</h1>

    <div class="row mb-4">
        <div class="col-md-8">
            <input type="text" class="form-control" placeholder="Search by title, code, or keyword..."
                   @bind="searchTerm" @bind:event="oninput" />
        </div>
        <div class="col-md-4">
            <select class="form-select" @bind="selectedDepartment">
                <option value="">All Departments</option>
                @foreach (var dept in CatalogService.GetDepartments())
                {
                    <option value="@dept.Id">@dept.Name</option>
                }
            </select>
        </div>
    </div>

    @{
        var results = CatalogService.SearchCourses(searchTerm, selectedDepartment);
    }

    <p class="text-muted">Showing @results.Count course(s)</p>

    <div class="row g-4">
        @foreach (var course in results)
        {
            var dept = CatalogService.GetDepartmentById(course.DepartmentId);
            <div class="col-md-6 col-lg-4">
                <div class="card course-card h-100 shadow-sm">
                    <div class="card-body d-flex flex-column">
                        <div class="d-flex justify-content-between align-items-start mb-2">
                            <span class="badge bg-primary">@course.Code</span>
                            <span class="badge bg-secondary">@course.Credits Credits</span>
                        </div>
                        <h5 class="card-title">@course.Title</h5>
                        <p class="card-text text-muted small flex-grow-1">@course.Description[..Math.Min(100, course.Description.Length)]...</p>
                        <p class="small mb-2"><strong>Schedule:</strong> @course.Schedule</p>
                        <p class="small mb-2"><strong>Department:</strong> @dept?.Name</p>
                        <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm mt-auto">View Details</a>
                    </div>
                </div>
            </div>
        }
    </div>

    @if (!results.Any())
    {
        <div class="text-center py-5">
            <h4 class="text-muted">No courses found matching your criteria.</h4>
            <p class="text-muted">Try adjusting your search or filter.</p>
        </div>
    }
</div>

@code {
    private string? searchTerm;
    private string? selectedDepartment;
}

@page "/courses/{Id:int}"
@inject CatalogService CatalogService

<PageTitle>@(course?.Title ?? "Course Not Found") - Crestwood University</PageTitle>

@if (course is null)
{
    <div class="container my-5 text-center">
        <h2>Course Not Found</h2>
        <p class="text-muted">The requested course could not be found.</p>
        <a href="/courses" class="btn btn-primary">Back to Catalog</a>
    </div>
}
else
{
    var dept = CatalogService.GetDepartmentById(course.DepartmentId);

    <div class="container my-5">
        <nav aria-label="breadcrumb">
            <ol class="breadcrumb">
                <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
                @if (dept is not null)
                {
                    <li class="breadcrumb-item"><a href="/departments/@dept.Slug">@dept.Name</a></li>
                }
                <li class="breadcrumb-item active">@course.Code</li>
            </ol>
        </nav>

        <div class="row">
            <div class="col-lg-8">
                <h1>@course.Title</h1>
                <p class="lead text-muted">@course.Code</p>

                <div class="d-flex gap-3 mb-4">
                    <span class="badge bg-primary fs-6">@course.Credits Credits</span>
                    @if (dept is not null)
                    {
                        <span class="badge bg-secondary fs-6">@dept.Name</span>
                    }
                </div>

                <h4>Description</h4>
                <p>@course.Description</p>

                <h4>Schedule</h4>
                <p>@course.Schedule</p>

                <a href="/enroll" class="btn btn-success btn-lg mt-3">Enroll in This Course</a>
            </div>

            <div class="col-lg-4">
                <div class="card shadow-sm">
                    <div class="card-body text-center">
                        <div class="bg-light rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style="width:80px;height:80px;">
                            <span class="fs-1">👤</span>
                        </div>
                        <h5 class="card-title">@course.Instructor.Name</h5>
                        <p class="card-text small">@course.Instructor.Bio</p>
                        <a href="mailto:@course.Instructor.Email" class="btn btn-outline-primary btn-sm">
                            ✉ @course.Instructor.Email
                        </a>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? course;

    protected override void OnInitialized()
    {
        course = CatalogService.GetCourseById(Id);
    }
}

@page "/departments/{Slug}"
@inject CatalogService CatalogService

<PageTitle>@(department?.Name ?? "Department Not Found") - Crestwood University</PageTitle>

@if (department is null)
{
    <div class="container my-5 text-center">
        <h2>Department Not Found</h2>
        <p class="text-muted">The requested department could not be found.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <div class="container my-5">
        <h1>@department.Name</h1>
        <p class="lead text-muted">@department.Description</p>

        <hr />

        <h3 class="mb-4">Courses in @department.Name</h3>

        <div class="row g-4">
            @foreach (var course in courses)
            {
                <div class="col-md-6">
                    <div class="card course-card h-100 shadow-sm">
                        <div class="card-body d-flex flex-column">
                            <div class="d-flex justify-content-between align-items-start mb-2">
                                <span class="badge bg-primary">@course.Code</span>
                                <span class="badge bg-secondary">@course.Credits Credits</span>
                            </div>
                            <h5 class="card-title">@course.Title</h5>
                            <p class="card-text text-muted small flex-grow-1">@course.Description[..Math.Min(120, course.Description.Length)]...</p>
                            <p class="small mb-2"><strong>Instructor:</strong> @course.Instructor.Name</p>
                            <p class="small mb-2"><strong>Schedule:</strong> @course.Schedule</p>
                            <a href="/courses/@course.Id" class="btn btn-outline-primary btn-sm mt-auto">View Details</a>
                        </div>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public string Slug { get; set; } = string.Empty;

    private Department? department;
    private List<Course> courses = new();

    protected override void OnInitialized()
    {
        department = CatalogService.GetDepartmentBySlug(Slug);
        if (department is not null)
        {
            courses = CatalogService.GetCoursesByDepartment(department.Id);
        }
    }
}

@page "/enroll"
@inject CatalogService CatalogService

<PageTitle>Enroll - Crestwood University</PageTitle>

<div class="container my-5">
    <div class="row justify-content-center">
        <div class="col-md-8 col-lg-6">
            <h1 class="mb-4">Course Enrollment</h1>

            @if (submitted)
            {
                <div class="alert alert-success">
                    <h4 class="alert-heading">Enrollment Request Submitted!</h4>
                    <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
                       <strong>@(CatalogService.GetCourseById(Model.CourseId)?.Title)</strong> has been received.</p>
                    <p class="mb-0">Student ID: @Model.StudentId</p>
                </div>
                <a href="/enroll" class="btn btn-primary">Submit Another Request</a>
            }
            else
            {
                <p class="text-muted">Fill out the form below to request enrollment in a course.</p>

                <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" method="post">
                    <AntiforgeryToken />
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                        <ValidationMessage For="() => Model.StudentName" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                        <ValidationMessage For="() => Model.StudentId" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                            <option value="0">-- Select a Course --</option>
                            @foreach (var course in CatalogService.GetAllCourses())
                            {
                                <option value="@course.Id">@course.Code - @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg w-100">Submit Enrollment Request</button>
                </EditForm>
            }
        </div>
    </div>
</div>

@code {
