                }
                <li class="breadcrumb-item active">@course.Code</li>
            </ol>
        </nav>

        <div class="row">
            <div class="col-lg-8">
                <h1>@course.Title</h1>
                <p class="lead text-muted">@course.Code</p>

                <div class="d-flex gap-3 mb-4">
                    <span class="badge bg-primary fs-6">@course.Credits Credits</span>
                    @if (dept is not null)
                    {
                        <span class="badge bg-secondary fs-6">@dept.Name</span>
                    }
                </div>

                <h4>Description</h4>
                <p>@course.Description</p>

                <h4>Schedule</h4>
                <p>@course.Schedule</p>

                <a href="/enroll" class="btn btn-success btn-lg mt-3">Enroll in This Course</a>
            </div>

            <div class="col-lg-4">
                <div class="card shadow-sm">
                    <div class="card-body text-center">
                        <div class="bg-light rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style="width:80px;height:80px;">
                            <span class="fs-1">👤</span>
                        </div>
                        <h5 class="card-title">@course.Instructor.Name</h5>
                        <p class="card-text small">@course.Instructor.Bio</p>
                        <a href="mailto:@course.Instructor.Email" class="btn btn-outline-primary btn-sm">
                            ✉ @course.Instructor.Email
                        </a>
                    </div>
                </div>
            </div>
        </div>
    </div>
}

