@inject CatalogService CatalogService

<PageTitle>Enroll - Crestwood University</PageTitle>

<div class="container my-5">
    <div class="row justify-content-center">
        <div class="col-md-8 col-lg-6">
            <h1 class="mb-4">Course Enrollment</h1>

            @if (submitted)
            {
                <div class="alert alert-success">
                    <h4 class="alert-heading">Enrollment Request Submitted!</h4>
                    <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
                       <strong>@(CatalogService.GetCourseById(Model.CourseId)?.Title)</strong> has been received.</p>
                    <p class="mb-0">Student ID: @Model.StudentId</p>
                </div>
                <a href="/enroll" class="btn btn-primary">Submit Another Request</a>
            }
            else
            {
                <p class="text-muted">Fill out the form below to request enrollment in a course.</p>

                <EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" method="post">
                    <AntiforgeryToken />
                    <DataAnnotationsValidator />
                    <ValidationSummary class="text-danger" />

                    <div class="mb-3">
                        <label for="studentName" class="form-label">Full Name</label>
                        <InputText id="studentName" class="form-control" @bind-Value="Model.StudentName" />
                        <ValidationMessage For="() => Model.StudentName" />
                    </div>

                    <div class="mb-3">
                        <label for="studentId" class="form-label">Student ID</label>
                        <InputText id="studentId" class="form-control" @bind-Value="Model.StudentId" />
                        <ValidationMessage For="() => Model.StudentId" />
                    </div>

                    <div class="mb-3">
                        <label for="courseId" class="form-label">Course</label>
                        <InputSelect id="courseId" class="form-select" @bind-Value="Model.CourseId">
                            <option value="0">-- Select a Course --</option>
                            @foreach (var course in CatalogService.GetAllCourses())
                            {
                                <option value="@course.Id">@course.Code - @course.Title</option>
                            }
                        </InputSelect>
                        <ValidationMessage For="() => Model.CourseId" />
                    </div>

                    <button type="submit" class="btn btn-success btn-lg w-100">Submit Enrollment Request</button>
                </EditForm>
            }
        </div>
    </div>
</div>

